void APawn::Internal_AddMovementInput(FVector WorldAccel, bool bForce /*=false*/)
{
	if (bForce || !IsMoveInputIgnored())
	{
		ControlInputVector += WorldAccel;
	}
}

FVector UCharacterMovementComponent::ConstrainInputAcceleration(const FVector& InputAcceleration) const
{
	// walking or falling pawns ignore up/down sliding
	const double InputAccelerationDotGravityNormal = FVector::DotProduct(InputAcceleration, -GetGravityDirection());
	if (!FMath::IsNearlyZero(InputAccelerationDotGravityNormal) && (IsMovingOnGround() || IsFalling()))
	{
		return FVector::VectorPlaneProject(InputAcceleration, -GetGravityDirection());
	}

	return InputAcceleration;
}


FVector UCharacterMovementComponent::ScaleInputAcceleration(const FVector& InputAcceleration) const
{
	return GetMaxAcceleration() * InputAcceleration.GetClampedToMaxSize(1.0f);
}

template<typename T>
inline TVector<T> TVector<T>::GetClampedToMaxSize(T MaxSize) const
{
    if (MaxSize < UE_KINDA_SMALL_NUMBER)
    {
        return ZeroVector;
    }

    const T VSq = SizeSquared();
    if (VSq > FMath::Square(MaxSize))
    {
        const T Scale = MaxSize * FMath::InvSqrt(VSq);
        return TVector<T>(X*Scale, Y*Scale, Z*Scale);
    }
    else
    {
        return *this;
    }	
}

pub fn view_relative_move_input(move_dir: Vec2, view_yaw: f32) -> Vec3 {
    let mut move_dir = move_dir.as_dvec2();
    let input_length_squared = move_dir.length_squared();
    if input_length_squared > 1.0 { move_dir *= input_length_squared.sqrt().recip(); }
    let source_degrees = (-(view_yaw as f64) - std::f64::consts::FRAC_PI_2).to_degrees() as f32;
    let (sin, cos) = crate::extensions::control_rig_math::rig_sin_cos(source_degrees.to_radians());
    let (sin, cos) = (f64::from(sin), f64::from(cos));
    let mut world = bevy::math::DVec3::new(cos * move_dir.y - sin * move_dir.x, 0.0,
        sin * move_dir.y + cos * move_dir.x);
    let world_length_squared = world.length_squared();
    if world_length_squared > 1.0 { world *= world_length_squared.sqrt().recip(); }
    world.as_vec3()
}

pub fn view_relative_move_direction(move_dir: Vec2, view_yaw: f32) -> Vec3 {
    view_relative_move_input(move_dir, view_yaw).normalize_or_zero()
}

